import json
def solve(inp):
    g=[r[:] for r in inp]; H=len(g); W=len(g[0])
    # find rectangles: borders of nonzero colors forming closed loops enclosing zero cells
    import numpy as np
    A=np.array(g)
    # detect connected components of nonzero cells (frame borders) via flood over nonzero
    seen=np.zeros_like(A,bool); rects=[]
    for i in range(H):
        for j in range(W):
            if A[i,j] and not seen[i,j]:
                stack=[(i,j)]; comp=[]; seen[i,j]=True
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and A[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=True; stack.append((ny,nx))
                rects.append(comp)
    for comp in rects:
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        if len(set(ys))==2 and len(set(xs))==2:
            continue
        rs=[min(ys),max(ys)]; cs=[min(xs),max(xs)]
        if rs[1]-rs[0]<2 or cs[1]-cs[0]<2: continue
        c=A[min(ys),min(cs)]
        inner=[(y,x) for y in range(rs[0]+1,rs[1]) for x in range(cs[0]+1,cs[1])]
        if all(A[y,x]==0 for y,x in inner):
            rects.append((rs,cs,int(c)))
    print([r for r in rects])
