                if len(comp)>=len(perim)-3 and all(A[y,x]!=0 for y,x in perim):
                    # fill inner cells with same parity as... find noise color adjacent inside
                    # noise color: most common nonzero non-col value among cells adjacent to perim inside
                    cands={int(A[y,x]) for y,x in inner if A[y,x]!=int(A[r0,c0])}
