                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and A[ny,nx]!=0 and not seen[ny,nx]:
                                seen[ny,nx]=True; st.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                perim={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in(r0,r1) or x in(c0,c1)}
                inner=set((y,x) for y in range(r0+1,r1) for x in range(c0+1,c1))
                if len(comp)>=len(perim)-3 and all(A[y,x]!=0 for y,x in perim) and len(inner)>0:
                    cands={int(A[y,x]) for y,x in inner if A[y,x]!=int(A[r0,c0])}
                    if len(cands)==1:
                        frames.append({'r0':r0,'r1':r1,'c0':c0,'c1':c1,
                                       'col':int(A[r0,c0]),'nc':cands.pop(),'inner':inner,
                                       'bbox':{(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)}})
    framecells=set().union(*[fr['bbox'] for fr in frames]) if frames else set()
    # candidate dots: nonzero cells not in any frame bbox, aligned (row or col in some frame's span)
    def is_frame_cell(y,x): return any((y,x) in fr['bbox'] for fr in frames)
    alldots=[(y,x,int(A[y][x])) for y in range(H) for x in range(W)
             if A[y][x]!=0 and not is_frame_cell(y,x)]
    frame_candidates={}
    for y,x,v in alldots:
        cand_frames=[f for f in frames if f['r0']<=y<=f['r1'] or f['c0']<=x<=f['c1']]
        if not cand_frames: continue
        d=min(abs(y-f['r0'])+abs(x-f['c0']) for f in cand_frames)
        near=[f for f in cand_frames if abs(y-f['r0'])+abs(x-f['c0'])==d]
        frame_candidates[(y,x,v)]=near
    # paint: each frame receives paint from its nearest candidate dot (one dot -> one frame)
    for (y,x,v),nf in frame_candidates.items():
        # pick frame: nearest by bbox distance, tie -> first
        best=min(nf,key=lambda f:(abs(y-f['r0'])+abs(x-f['c0']), id(f)))
        phase=(y+x)%2
        for fy,fy2 in [(best['r0'],best['c0'])]: pass
        fr=best
        for yy,xx in sorted(fr['inner']):
            if (yy+xx)%2==phase: g[yy][xx]=v
    # optional: remove unused dots
    used=set(frame_candidates.keys())
    if delete_unused:
        for (y,x,v) in alldots:
            if (y,x,v) not in used: g[y][x]=0
    return g
