def find_frames(A):
    """8-connected components of nonzero cells that form a hollow rectangle: 
    bbox perimeter all nonzero, size >= perim-3, interior contains exactly one noise color besides frame color."""
    H,W=A.shape; seen=np.zeros_like(A,bool); out=[]
    for i in range(H):
        for j in range(W):
            if A[i,j]!=0 and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and A[ny,nx]!=0 and not seen[ny,nx]:
                                seen[ny,nx]=True; q.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                perim={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in(r0,r1) or x in(c0,c1)}
                inner={(y,x) for y in range(r0+1,r1) for x in range(c0+1,c1)}
                if len(comp)>=len(perim)-3 and all(A[y,x]!=0 for y,x in perim) and len(inner)>0:
                    # frame color = most common on perimeter; noise colors inside
