import numpy as np
from collections import Counter as C2
def frames_of(A):
    H,W=A.shape; cands=[]
    for y0 in range(H-2):
        for x0 in range(W-2):
            for h in range(3,H-y0+1):
                for w in range(3,W-x0+1):
                    y1,x1=y0+h-1,x0+w-1
                    if all(A[y,x]!=0 for y in (y0,y1) for x in range(x0,x1+1)) and all(A[y,x]!=0 for x in (x0,x1) for y in range(y0,y1+1)):
                        cands.append((y0,y1,x0,x1))
    maxs=[t for t in cands if not any(t[0]>=b[0] and t[1]<=b[1] and t[2]>=b[2] and t[3]<=b[3] for b in cands if t!=b)]
    return maxs
def solve(inp,keep_inner=False):
    A=np.array(inp); H,W=A.shape
    frs=list(frames_of(A))
    g=[row[:] for row in inp]
    def inb(y,x): return any(f_[0]<=y<=f_[1] and f_[2]<=x<=f_[3] for f_ in frs)
    bordercols={int(A[f_[0],f_[2]]) for f_ in frs}
    dots=[(int(y),int(x),int(A[y,x])) for y in range(H) for x in range(W) if A[y,x]!=0 and int(A[y,x]) not in bordercols]
    cnt=C2(dv for _,_,dv in dots)
    col_s=sorted(cnt.items(),key=lambda kv:(-kv[1],kv[0]))
    frs_sorted=sorted(frs,key=lambda f:-((f_[1]-f_[0]+1)*(f_[3]-f_[2]+1)))
    for rank,f_ in enumerate(frs_sorted):
        v=col_s[rank%len(col_s)][0]
        phase=(f_[0]+f_[2])%2
        inner={(yy,xx) for yy in range(f_[0]+1,f_[1]) for xx in range(f_[2]+1,f_[3])}
        for (yy,xx) in inner:
            if keep_inner and A[yy,xx]!=0 and not ((yy+xx)%2==phase): continue
            g[yy][xx]= v if (yy+xx)%2==phase else 0
    for y in range(H):
        for x in range(W):
            if A[y,x]!=0 and not inb(y,x) and not keep_inner or (A[y,x]!=0 and inb(y,x) and not keep_inner):
                pass
    # erase stray dots outside frames
    for y in range(H):
        for x in range(W):
            if A[y,x]!=0 and not inb(y,x): g[y][x]=0
    return g
ok=True
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    r=solve(G[k+' input']); exp=G[k+' output']
    bad=[(y,x,r[y][x],exp[y][x]) for y in range(len(r)) for x in range(len(r[0])) if r[y][x]!=exp[y][x]]
    ok &= len(bad)==0
    print(k,'ndiff',len(bad))
print('ALL OK' if ok else 'no')
