diffs=[(y,x,int(out[y][x]),G['Test input'][y][x]) for y in range(len(out)) for x in range(len(out[0])) if out[y][x]!=G['Test input'][y][x]]
print(len(diffs),'changed cells; sample:',diffs[:10])
