    dots=[(int(y),int(x),int(A[y,x])) for y in range(H) for x in range(W) if A[y,x]!=0 and int(A[y,x]) not in {int(A[f_[0],f_[2]]) for f_ in frs}]
    cnt=C2(dv for _,_,dv in dots)
    col_s=sorted(cnt.items(),key=lambda kv:(-kv[1],kv[0]))
